elect></label><label>Miktar<input type="number" name="quantity" min="0.001" step="0.001" value="1"></label><button class="btn secondary">Parça ekle</button></form><div class="table-wrap"><table class="data-table"><thead><tr><th>Parça</th><th>Miktar</th><th>Birim fiyat</th><th>Toplam</th></tr></thead><tbody><?php foreach($parts as $p): ?><tr><td><?= kd_e($p['product_name']) ?></td><td><?= kd_e($p['quantity']) ?></td><td><?= number_format((float)$p['unit_price'],2,',','.') ?> ₺</td><td><?= number_format((float)$p['line_total'],2,',','.') ?> ₺</td></tr><?php endforeach; ?><?php if(!$parts): ?><tr><td colspan="4">Parça eklenmemiş.</td></tr><?php endif; ?></tbody></table></div><h3>İşlem geçmişi</h3><?php foreach($history as $h): ?><div class="pos-recent"><span><?= kd_e($h['from_status']??'—') ?> → <?= kd_e($h['to_status']) ?> · <?= kd_e($h['note']??'') ?></span><small><?= kd_e($h['created_at']) ?></small></div><?php endforeach; ?></section>
<?php else: ?><div class="marketplace-grid"><section class="panel customer-form-panel"><h3>Yeni servis kaydı</h3><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="create"><label>Müşteri<select name="customer_id"><option value="0">Seçilmedi</option><?php foreach($customers as $c): ?><option value="<?= (int)$c['id'] ?>"><?= kd_e($c['name']) ?></option><?php endforeach; ?></select></label><label>Servis deposu<select name="warehouse_id" required><?php foreach($warehouses as $warehouse): ?><option value="<?= (int)$warehouse['id'] ?>" <?= (int)$warehouse['id']===(int)$defaultWarehouseId?'selected':'' ?>><?= kd_e($warehouse['name'].' · '.$warehouse['code']) ?></option><?php endforeach; ?></select></label><label>Cihaz / ürün<input name="device_name" required></label><label>Seri numarası<input name="serial_number"></label><label>Arıza açıklaması<textarea name="issue_description" required rows="3"></textarea></label><label>Öncelik<select name="priority"><option value="normal">Normal</option><option value="high">Yüksek</option><option value="urgent">Acil</option><option value="low">Düşük</option></select></label><label>Atanan personel<select name="assigned_user_id"><option value="0">Atanmamış</option><?php foreach($users as $u): ?><option value="<?= (int)$u['id'] ?>"><?= kd_e($u['name']) ?></option><?php endforeach; ?></select></label><label>Tahmini maliyet<input type="number" name="estimated_cost" min="0" step="0.01"></label><label>Teslim tarihi<input type="date" name="due_at"></label><button class="btn primary" <?= !$warehouses?'disabled':'' ?>>Servis kaydı aç</button></form></section><section class="panel customer-list-panel"><h3>Servis iş emirleri</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Servis</th><th>Müşteri</th><th>Cihaz</th><th>Depo</th><th>Durum</th><th>Öncelik</th><th>Atanan</th><th></th></tr></thead><tbody><?php foreach($jobs as $j): ?><tr><td><?= kd_e($j['service_number']) ?></td><td><?= kd_e($j['customer_name']??'—') ?></td><td><?= kd_e($j['device_name']) ?></td><td><?= kd_e($j['warehouse_name']??'—') ?></td><td><?= kd_e($j['status']) ?></td><td><?= kd_e($j['priority']) ?></td><td><?= kd_e($j['assignee_name']??'—') ?></td><td><a class="btn secondary action-link" href="index.php?page=service&id=<?= (int)$j['id'] ?>">Aç</a></td></tr><?php endforeach; ?><?php if(!$jobs): ?><tr><td colspan="8">Servis kaydı bulunmuyor.</td></tr><?php endif; ?></tbody></table></div></section></div><?php endif; ?>
